  CONSTRAINT pk_product PRIMARY KEY (product_id),
  CONSTRAINT uq_product_product_code UNIQUE (product_code)
);
COMMENT ON TABLE product IS 'An insurance product offered to the market, such as a personal auto program, a businessowners policy, a 20-year level term life plan or a deferred indexed annuity.';

CREATE TABLE product_filing (
  product_filing_id uuid NOT NULL,
  product_id uuid NOT NULL,
  jurisdiction_code varchar(6) NOT NULL,
  insurer_id uuid,
  filing_type text NOT NULL CONSTRAINT ck_product_filing_filing_type CHECK (filing_type IN ('RATE', 'RULE', 'FORM', 'RATE_AND_RULE', 'PRODUCT', 'ADVERTISING')),
  filing_status text NOT NULL CONSTRAINT ck_product_filing_filing_status CHECK (filing_status IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'ACKNOWLEDGED', 'DISAPPROVED', 'WITHDRAWN')),
  tracking_number varchar(50),
  overall_rate_change_percent numeric(9,4),
  submitted_on date,
  disposition_on date,
  new_business_effective_on date,
  renewal_effective_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_product_filing PRIMARY KEY (product_filing_id)
);
COMMENT ON TABLE product_filing IS 'A rate, rule or form filing made with a regulator for a product (typically via SERFF).';

CREATE TABLE product_form (
  product_form_id uuid NOT NULL,
  product_id uuid NOT NULL,
  form_id uuid NOT NULL,
  jurisdiction_code varchar(6),
  coverage_definition_id uuid,
  form_usage text NOT NULL CONSTRAINT ck_product_form_form_usage CHECK (form_usage IN ('MANDATORY', 'CONDITIONAL', 'OPTIONAL')),
  product_filing_id uuid,
  effective_on date NOT NULL,
  expires_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_product_form PRIMARY KEY (product_form_id)
);
COMMENT ON TABLE product_form IS 'Approval of a form for use with a product in a jurisdiction.';

CREATE TABLE product_jurisdiction (
  product_jurisdiction_id uuid NOT NULL,
  product_id uuid NOT NULL,
  jurisdiction_code varchar(6) NOT NULL,
  insurer_id uuid NOT NULL,
  new_business_effective_on date NOT NULL,
  renewal_effective_on date,
  closed_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_product_jurisdiction PRIMARY KEY (product_jurisdiction_id)
);
COMMENT ON TABLE product_jurisdiction IS 'Availability of a product in a jurisdiction through a specific writing company.';

CREATE TABLE insurable_object (
  insurable_object_id uuid NOT NULL,
  insurable_object_type text NOT NULL CONSTRAINT ck_insurable_object_insurable_object_type CHECK (insurable_object_type IN ('VEHICLE', 'STRUCTURE', 'PERSON', 'BUSINESS_OPERATION', 'SCHEDULED_ITEM', 'WATERCRAFT', 'AIRCRAFT', 'ANIMAL', 'BOND_OBLIGATION', 'OTHER')),
  description varchar(500),
  party_id uuid,
  address_id uuid,
  additional_attributes jsonb,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_insurable_object PRIMARY KEY (insurable_object_id)
);
COMMENT ON TABLE insurable_object IS 'A real-world thing, person or activity exposed to loss, independent of any policy. Supertype for line-specific objects (vehicle, structure, watercraft, scheduled item, business operation). The same object can be insured on successive or multiple policies.';

CREATE TABLE policy (
  policy_id uuid NOT NULL,
  policy_number varchar(30) NOT NULL,
  product_id uuid NOT NULL,
  insurer_id uuid NOT NULL,
  line_of_business_code varchar(30) NOT NULL,
  policy_structure text NOT NULL CONSTRAINT ck_policy_policy_structure CHECK (policy_structure IN ('INDIVIDUAL', 'GROUP_MASTER', 'CERTIFICATE')),
  master_policy_id uuid,
  policy_status text NOT NULL CONSTRAINT ck_policy_policy_status CHECK (policy_status IN ('PENDING', 'IN_FORCE', 'CANCELLED', 'EXPIRED', 'NON_RENEWED', 'LAPSED', 'REDUCED_PAID_UP', 'EXTENDED_TERM', 'SURRENDERED', 'MATURED', 'ANNUITIZED', 'DEATH_CLAIM', 'CONVERTED', 'RESCINDED')),
  governing_jurisdiction_code varchar(6) NOT NULL,
  currency_code varchar(3) NOT NULL,
  original_inception_date date NOT NULL,
  submission_id uuid,
  replaces_policy_id uuid,
  is_assumed_business boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy PRIMARY KEY (policy_id),
  CONSTRAINT uq_policy_policy_number UNIQUE (policy_number)
);
COMMENT ON TABLE policy IS 'An insurance contract between an insurer and a policyholder, identified by a policy number that persists across renewals. For group business the master contract and each certificate are policies linked by master_policy_id.';

CREATE TABLE policy_coverage (
  policy_coverage_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  policy_risk_id uuid,
  coverage_definition_id uuid NOT NULL,
  coverage_trigger text CONSTRAINT ck_policy_coverage_coverage_trigger CHECK (coverage_trigger IN ('OCCURRENCE', 'CLAIMS_MADE', 'CLAIMS_MADE_AND_REPORTED')),
  retroactive_date date,
  extended_reporting_end_date date,
  asl_code varchar(10),
  annualized_premium_amount numeric(18,2),
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_coverage PRIMARY KEY (policy_coverage_id)
);
COMMENT ON TABLE policy_coverage IS 'A coverage, benefit or rider in force on a policy, either at policy level or for one risk.';

CREATE TABLE policy_coverage_term (
  policy_coverage_term_id uuid NOT NULL,
  policy_coverage_id uuid NOT NULL,
  coverage_term_definition_id uuid NOT NULL,
  term_value numeric(18,6),
  term_code_value varchar(50),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_coverage_term PRIMARY KEY (policy_coverage_term_id),
  CONSTRAINT uq_policy_coverage_term_policy_coverage_id_coverage_te_eb49b805 UNIQUE (policy_coverage_id, coverage_term_definition_id)
);
COMMENT ON TABLE policy_coverage_term IS 'The selected value of a limit, deductible or other term for a coverage on a policy.';

CREATE TABLE policy_form (
  policy_form_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  form_id uuid NOT NULL,
  policy_coverage_id uuid,
  policy_risk_id uuid,
  variable_data jsonb,
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_form PRIMARY KEY (policy_form_id)
);
COMMENT ON TABLE policy_form IS 'A form or endorsement attached to a policy.';

CREATE TABLE policy_location (
  policy_location_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  location_number integer NOT NULL,
  address_id uuid NOT NULL,
  is_primary boolean,
  territory_code varchar(20),
  description varchar(500),
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_location PRIMARY KEY (policy_location_id)
);
COMMENT ON TABLE policy_location IS 'A premises or location scheduled on a policy.';

CREATE TABLE policy_party (
  policy_party_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  party_id uuid NOT NULL,
  policy_party_role text NOT NULL CONSTRAINT ck_policy_party_policy_party_role CHECK (policy_party_role IN ('NAMED_INSURED', 'ADDITIONAL_NAMED_INSURED', 'ADDITIONAL_INSURED', 'OWNER', 'JOINT_OWNER', 'INSURED_LIFE', 'ANNUITANT', 'JOINT_ANNUITANT', 'PAYOR', 'SUBSCRIBER', 'GROUP_SPONSOR', 'MORTGAGEE', 'LIENHOLDER', 'LOSS_PAYEE', 'LESSOR', 'CERTIFICATE_HOLDER', 'ASSIGNEE', 'TRUSTEE', 'THIRD_PARTY_DESIGNEE', 'PRINCIPAL', 'OBLIGEE')),
  policy_risk_id uuid,
  is_primary boolean,
  interest_rank integer,
  reference_number varchar(50),
  mailing_address_id uuid,
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_party PRIMARY KEY (policy_party_id)
);
COMMENT ON TABLE policy_party IS 'A party''s role on a policy, optionally scoped to one risk (e.g. lienholder on a vehicle, mortgagee on a building).';

CREATE TABLE policy_producer (
  policy_producer_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  producer_id uuid NOT NULL,
  policy_producer_role text NOT NULL CONSTRAINT ck_policy_producer_policy_producer_role CHECK (policy_producer_role IN ('WRITING', 'SERVICING', 'SPLIT', 'OVERRIDE', 'WHOLESALE')),
  commission_split_percent numeric(9,4),
  effective_date date NOT NULL,
  expiration_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_producer PRIMARY KEY (policy_producer_id)
);
COMMENT ON TABLE policy_producer IS 'A producer credited with a policy, with their share of commission.';

CREATE TABLE policy_rating_modifier (
  policy_rating_modifier_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  policy_risk_id uuid,
  policy_coverage_id uuid,
  rating_modifier_type text NOT NULL CONSTRAINT ck_policy_rating_modifier_rating_modifier_type CHECK (rating_modifier_type IN ('DISCOUNT', 'SURCHARGE', 'EXPERIENCE_MODIFICATION', 'SCHEDULE_RATING', 'IRPM', 'TIER', 'INSURANCE_SCORE', 'MULTI_POLICY', 'LOSS_FREE', 'PREMIUM_DISCOUNT', 'RISK_CLASS', 'TABLE_RATING', 'FLAT_EXTRA', 'OTHER')),
  modifier_code varchar(50) NOT NULL,
  factor numeric(18,8),
  amount numeric(18,2),
  jurisdiction_code varchar(6),
  justification text,
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_rating_modifier PRIMARY KEY (policy_rating_modifier_id)
);
COMMENT ON TABLE policy_rating_modifier IS 'A discount, surcharge, experience modification, schedule credit or underwriting class applied in rating a policy, risk or coverage.';

CREATE TABLE policy_risk (
  policy_risk_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  insurable_object_id uuid NOT NULL,
  risk_number integer NOT NULL,
  policy_location_id uuid,
  rating_jurisdiction_code varchar(6),
  territory_code varchar(20),
  insured_value_amount numeric(18,2),
  additional_attributes jsonb,
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_risk PRIMARY KEY (policy_risk_id)
);
COMMENT ON TABLE policy_risk IS 'An insurable object as insured under a policy (a risk unit): the vehicle on an auto policy, the building at a location, the insured life, the operations of a business in a state. Supertype for line-specific rating detail.';

CREATE TABLE policy_term (
  policy_term_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  term_number integer NOT NULL,
  effective_date date NOT NULL,
  expiration_date date,
  policy_term_status text NOT NULL CONSTRAINT ck_policy_term_policy_term_status CHECK (policy_term_status IN ('PENDING', 'IN_FORCE', 'CANCELLED', 'EXPIRED', 'VOIDED')),
  cancellation_date date,
  cancellation_reason text CONSTRAINT ck_policy_term_cancellation_reason CHECK (cancellation_reason IN ('INSURED_REQUEST', 'NON_PAYMENT', 'UNDERWRITING', 'MATERIAL_MISREPRESENTATION', 'REWRITTEN', 'SOLD_OR_NO_LONGER_OWNED', 'COVERAGE_PLACED_ELSEWHERE', 'DECEASED', 'COMPANY_WITHDRAWAL', 'OTHER')),
  cancellation_method text CONSTRAINT ck_policy_term_cancellation_method CHECK (cancellation_method IN ('PRO_RATA', 'SHORT_RATE', 'FLAT')),
  product_filing_id uuid,
  is_auditable boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_term PRIMARY KEY (policy_term_id),
  CONSTRAINT uq_policy_term_policy_id_term_number UNIQUE (policy_id, term_number)
);
COMMENT ON TABLE policy_term IS 'A contiguous period of coverage under a policy, typically 6 or 12 months for P&C and plan-year for health. Continuous contracts (life, annuity) have a single open-ended term.';

CREATE TABLE policy_transaction (
  policy_transaction_id uuid NOT NULL,
  policy_term_id uuid NOT NULL,
  sequence_number integer NOT NULL,
  policy_transaction_type text NOT NULL CONSTRAINT ck_policy_transaction_policy_transaction_type CHECK (policy_transaction_type IN ('NEW_BUSINESS', 'ENDORSEMENT', 'RENEWAL', 'CANCELLATION', 'REINSTATEMENT', 'REWRITE', 'NON_RENEWAL', 'PREMIUM_AUDIT', 'EXTENSION', 'LAPSE', 'SURRENDER', 'CONVERSION', 'MATURITY', 'ANNUITIZATION', 'DEATH', 'RESCISSION', 'ANNIVERSARY')),
  policy_transaction_status text NOT NULL CONSTRAINT ck_policy_transaction_policy_transaction_status CHECK (policy_transaction_status IN ('DRAFT', 'QUOTED', 'BOUND', 'ISSUED', 'REVERSED', 'VOIDED')),
  effective_date date NOT NULL,
  processed_at timestamptz NOT NULL,
  accounting_date date,
  is_out_of_sequence boolean,
  reverses_transaction_id uuid,
  reason_code varchar(50),
  description text,
  processed_by_staff_member_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_policy_transaction PRIMARY KEY (policy_transaction_id),
  CONSTRAINT uq_policy_transaction_policy_term_id_sequence_number UNIQUE (policy_term_id, sequence_number)
);
COMMENT ON TABLE policy_transaction IS 'A dated change to a policy: new business, endorsement, renewal, cancellation, reinstatement, audit and so on. The unit of policy versioning and the source of all written premium.';

CREATE TABLE premium_transaction (
  premium_transaction_id uuid NOT NULL,
  policy_transaction_id uuid NOT NULL,
  policy_coverage_id uuid,
  premium_charge_type text NOT NULL CONSTRAINT ck_premium_transaction_premium_charge_type CHECK (premium_charge_type IN ('PREMIUM', 'MINIMUM_PREMIUM_ADJUSTMENT', 'POLICY_FEE', 'INSTALLMENT_FEE', 'INSPECTION_FEE', 'BROKER_FEE', 'PREMIUM_TAX', 'SURPLUS_LINES_TAX', 'STAMPING_FEE', 'STATE_SURCHARGE', 'TERRORISM_PREMIUM', 'EXPENSE_CONSTANT', 'OTHER_FEE')),
  amount numeric(18,2) NOT NULL,
  jurisdiction_code varchar(6) NOT NULL,
  asl_code varchar(10),
  earning_start_date date NOT NULL,
  earning_end_date date NOT NULL,
  accounting_date date NOT NULL,
  is_commissionable boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_premium_transaction PRIMARY KEY (premium_transaction_id)
);
COMMENT ON TABLE premium_transaction IS 'The written-premium ledger: one signed amount per policy transaction, coverage, state and charge type, with the coverage period it is earned over. Written, earned, unearned and in-force premium are all derived from these rows.';

CREATE TABLE prior_coverage (
  prior_coverage_id uuid NOT NULL,
  submission_id uuid,
  policy_id uuid,
  carrier_name varchar(255) NOT NULL,
  carrier_insurer_id uuid,
  prior_policy_number varchar(50),
  line_of_business_code varchar(30),
  effective_date date,
  expiration_date date,
  premium_amount numeric(18,2),
  limits_description varchar(200),
  claim_count integer,
  incurred_loss_amount numeric(18,2),
  had_lapse boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_prior_coverage PRIMARY KEY (prior_coverage_id)
);
COMMENT ON TABLE prior_coverage IS 'Insurance an applicant held previously with any carrier, as declared or verified at underwriting.';

CREATE TABLE quote (
  quote_id uuid NOT NULL,
  submission_id uuid NOT NULL,
  quote_number varchar(30) NOT NULL,
  version_number integer NOT NULL,
  quote_status text NOT NULL CONSTRAINT ck_quote_quote_status CHECK (quote_status IN ('DRAFT', 'RATED', 'PRESENTED', 'ACCEPTED', 'BOUND', 'DECLINED', 'EXPIRED')),
  proposed_effective_date date,
  proposed_expiration_date date,
  total_premium_amount numeric(18,2),
  total_taxes_fees_amount numeric(18,2),
  valid_until date,
  rated_at timestamptz,
  quote_data jsonb,
  bound_policy_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_quote PRIMARY KEY (quote_id),
  CONSTRAINT uq_quote_quote_number_version_number UNIQUE (quote_number, version_number)
);
COMMENT ON TABLE quote IS 'A priced offer made in response to a submission. A submission may have several quote versions or options; at most one is bound into a policy transaction.';

CREATE TABLE submission (
  submission_id uuid NOT NULL,
  submission_number varchar(30) NOT NULL,
  applicant_party_id uuid NOT NULL,
  product_id uuid NOT NULL,
  producer_id uuid,
  jurisdiction_code varchar(6),
  submission_status text NOT NULL CONSTRAINT ck_submission_submission_status CHECK (submission_status IN ('RECEIVED', 'IN_REVIEW', 'QUOTED', 'BOUND', 'DECLINED', 'WITHDRAWN', 'EXPIRED')),
  is_renewal boolean,
  renewal_of_policy_id uuid,
  channel varchar(30),
  received_at timestamptz NOT NULL,
  requested_effective_date date,
  assigned_underwriter_id uuid,
  application_data jsonb,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_submission PRIMARY KEY (submission_id),
  CONSTRAINT uq_submission_submission_number UNIQUE (submission_number)
);
COMMENT ON TABLE submission IS 'A request for insurance received from an applicant or producer, prior to and independent of any policy.';

CREATE TABLE underlying_policy (
  underlying_policy_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  internal_policy_id uuid,
  carrier_name varchar(255),
  underlying_policy_number varchar(50),
  line_of_business_code varchar(30),
  per_occurrence_limit_amount numeric(18,2),
  aggregate_limit_amount numeric(18,2),
  limits_description varchar(200),
  underlying_effective_date date,
  underlying_expiration_date date,
  effective_date date NOT NULL,
  expiration_date date,
  added_by_transaction_id uuid NOT NULL,
  removed_by_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_underlying_policy PRIMARY KEY (underlying_policy_id)
);
COMMENT ON TABLE underlying_policy IS 'A primary policy scheduled beneath an umbrella or excess policy, whether written by this insurer or another.';

CREATE TABLE underwriting_decision (
  underwriting_decision_id uuid NOT NULL,
  submission_id uuid,
  policy_transaction_id uuid,
  underwriting_decision_type text NOT NULL CONSTRAINT ck_underwriting_decision_underwriting_decision_type CHECK (underwriting_decision_type IN ('APPROVED', 'APPROVED_WITH_CONDITIONS', 'COUNTER_OFFER', 'REFERRED', 'POSTPONED', 'DECLINED', 'INCOMPLETE')),
  is_automated boolean,
  decided_by_staff_member_id uuid,
  decided_at timestamptz NOT NULL,
  reason_code varchar(50),
  conditions text,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_underwriting_decision PRIMARY KEY (underwriting_decision_id)
);
COMMENT ON TABLE underwriting_decision IS 'A recorded underwriting decision on a submission or policy transaction.';

CREATE TABLE driver_incident (
  driver_incident_id uuid NOT NULL,
  policy_driver_id uuid NOT NULL,
  driver_incident_type text NOT NULL CONSTRAINT ck_driver_incident_driver_incident_type CHECK (driver_incident_type IN ('AT_FAULT_ACCIDENT', 'NOT_AT_FAULT_ACCIDENT', 'MINOR_VIOLATION', 'MAJOR_VIOLATION', 'DUI', 'SUSPENSION', 'COMPREHENSIVE_CLAIM')),
  incident_date date NOT NULL,
  conviction_date date,
  violation_code varchar(30),
  description varchar(500),
  source varchar(30),
  paid_amount numeric(18,2),
  is_chargeable boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_driver_incident PRIMARY KEY (driver_incident_id)
);
COMMENT ON TABLE driver_incident IS 'An accident, violation or claim on a driver''s record used in rating, from an MVR, CLUE report or self-report.';

CREATE TABLE dwelling_risk (
  policy_risk_id uuid NOT NULL,
  homeowners_form text CONSTRAINT ck_dwelling_risk_homeowners_form CHECK (homeowners_form IN ('HO2', 'HO3', 'HO4', 'HO5', 'HO6', 'HO8', 'DP1', 'DP3')),
  residence_type text CONSTRAINT ck_dwelling_risk_residence_type CHECK (residence_type IN ('SINGLE_FAMILY', 'TWO_TO_FOUR_FAMILY', 'CONDO_UNIT', 'TOWNHOUSE', 'APARTMENT', 'MOBILE_HOME')),
  dwelling_occupancy text CONSTRAINT ck_dwelling_risk_dwelling_occupancy CHECK (dwelling_occupancy IN ('OWNER_PRIMARY', 'OWNER_SECONDARY', 'SEASONAL', 'TENANT', 'VACANT', 'UNDER_CONSTRUCTION')),
  replacement_cost_amount numeric(18,2),
  replacement_cost_estimated_on date,
  valuation_method text CONSTRAINT ck_dwelling_risk_valuation_method CHECK (valuation_method IN ('REPLACEMENT_COST', 'ACTUAL_CASH_VALUE', 'AGREED_VALUE', 'STATED_AMOUNT', 'FUNCTIONAL_REPLACEMENT_COST', 'MARKET_VALUE')),
  protection_class varchar(5),
  distance_to_fire_station_miles numeric(18,6),
  distance_to_hydrant_feet integer,
  purchase_date date,
  has_swimming_pool boolean,
  has_trampoline boolean,
  has_wood_stove boolean,
  has_restricted_dog_breed boolean,
  has_wind_mitigation_features boolean,
  has_water_leak_detection boolean,
  household_member_count integer,
  home_business_description varchar(200),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_dwelling_risk PRIMARY KEY (policy_risk_id)
);
COMMENT ON TABLE dwelling_risk IS 'Policy-specific rating detail for a dwelling or residence on a homeowners, condo, renters or dwelling fire policy.';

CREATE TABLE personal_auto_risk (
  policy_risk_id uuid NOT NULL,
  vehicle_use text CONSTRAINT ck_personal_auto_risk_vehicle_use CHECK (vehicle_use IN ('PLEASURE', 'COMMUTE', 'BUSINESS', 'FARM', 'RIDESHARE')),
  annual_mileage integer,
