  repaid_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_contract_loan PRIMARY KEY (contract_loan_id)
);
COMMENT ON TABLE contract_loan IS 'A loan taken against the cash value of a contract.';

CREATE TABLE contract_value (
  contract_value_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  valuation_date date NOT NULL,
  account_value_amount numeric(18,2),
  cash_surrender_value_amount numeric(18,2),
  surrender_charge_amount numeric(18,2),
  loan_balance_amount numeric(18,2),
  death_benefit_amount numeric(18,2),
  net_amount_at_risk_amount numeric(18,2),
  cost_basis_amount numeric(18,2),
  cumulative_premium_amount numeric(18,2),
  paid_up_additions_face_amount numeric(18,2),
  dividend_accumulation_amount numeric(18,2),
  guaranteed_benefit_base_amount numeric(18,2),
  free_withdrawal_remaining_amount numeric(18,2),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_contract_value PRIMARY KEY (contract_value_id),
  CONSTRAINT uq_contract_value_policy_id_valuation_date UNIQUE (policy_id, valuation_date)
);
COMMENT ON TABLE contract_value IS 'Snapshot of a life or annuity contract''s values on a valuation date (anniversary, month-end or on demand).';

CREATE TABLE coverage_insured (
  coverage_insured_id uuid NOT NULL,
  policy_coverage_id uuid NOT NULL,
  party_id uuid NOT NULL,
  insured_role text NOT NULL CONSTRAINT ck_coverage_insured_insured_role CHECK (insured_role IN ('PRIMARY', 'JOINT', 'SPOUSE', 'CHILD', 'OTHER_INSURED')),
  issue_age integer NOT NULL,
  age_basis varchar(20),
  rated_gender text CONSTRAINT ck_coverage_insured_rated_gender CHECK (rated_gender IN ('FEMALE', 'MALE', 'NONBINARY', 'UNKNOWN')),
  underwriting_class varchar(30),
  tobacco_status text CONSTRAINT ck_coverage_insured_tobacco_status CHECK (tobacco_status IN ('NON_TOBACCO', 'TOBACCO', 'UNISMOKE')),
  table_rating varchar(5),
  flat_extra_per_thousand numeric(18,8),
  flat_extra_end_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_coverage_insured PRIMARY KEY (coverage_insured_id),
  CONSTRAINT uq_coverage_insured_policy_coverage_id_party_id UNIQUE (policy_coverage_id, party_id)
);
COMMENT ON TABLE coverage_insured IS 'A person whose life is insured under a coverage or rider, with the underwriting class assigned to them.';

CREATE TABLE investment_fund (
  investment_fund_id uuid NOT NULL,
  fund_code varchar(30) NOT NULL,
  name varchar(255) NOT NULL,
  fund_type text NOT NULL CONSTRAINT ck_investment_fund_fund_type CHECK (fund_type IN ('FIXED_ACCOUNT', 'VARIABLE_SUBACCOUNT', 'INDEXED_STRATEGY', 'MVA_GUARANTEE_PERIOD', 'LOAN_COLLATERAL_ACCOUNT', 'DOLLAR_COST_AVERAGING')),
  underlying_cusip varchar(9),
  index_name varchar(100),
  crediting_method varchar(50),
  expense_ratio_percent numeric(9,4),
  opened_on date,
  closed_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_investment_fund PRIMARY KEY (investment_fund_id),
  CONSTRAINT uq_investment_fund_fund_code UNIQUE (fund_code)
);
COMMENT ON TABLE investment_fund IS 'An investment option available within life and annuity products: fixed account, variable subaccount or index crediting strategy.';

CREATE TABLE life_claim_detail (
  claim_id uuid NOT NULL,
  life_claim_type text NOT NULL CONSTRAINT ck_life_claim_detail_life_claim_type CHECK (life_claim_type IN ('DEATH', 'ACCIDENTAL_DEATH', 'ACCELERATED_DEATH_BENEFIT', 'WAIVER_OF_PREMIUM', 'CRITICAL_ILLNESS', 'LONG_TERM_CARE_RIDER', 'ANNUITY_DEATH', 'MATURITY')),
  insured_party_id uuid NOT NULL,
  date_of_death date,
  manner_of_death text CONSTRAINT ck_life_claim_detail_manner_of_death CHECK (manner_of_death IN ('NATURAL', 'ACCIDENT', 'SUICIDE', 'HOMICIDE', 'PENDING', 'UNDETERMINED')),
  cause_of_death_code_value_id uuid,
  death_jurisdiction_code varchar(6),
  is_within_contestable_period boolean,
  proof_of_loss_received_on date,
  death_certificate_document_id uuid,
  gross_benefit_amount numeric(18,2),
  loan_offset_amount numeric(18,2),
  premium_adjustment_amount numeric(18,2),
  claim_interest_amount numeric(18,2),
  source_of_death_notice varchar(30),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_life_claim_detail PRIMARY KEY (claim_id)
);
COMMENT ON TABLE life_claim_detail IS 'Life and annuity specific attributes of a claim.';

CREATE TABLE life_policy_detail (
  policy_id uuid NOT NULL,
  life_plan_type text NOT NULL CONSTRAINT ck_life_policy_detail_life_plan_type CHECK (life_plan_type IN ('TERM', 'WHOLE_LIFE', 'UNIVERSAL_LIFE', 'INDEXED_UNIVERSAL_LIFE', 'VARIABLE_UNIVERSAL_LIFE', 'VARIABLE_LIFE', 'FINAL_EXPENSE', 'GROUP_TERM', 'CREDIT_LIFE', 'ENDOWMENT')),
  face_amount numeric(18,2) NOT NULL,
  death_benefit_option text CONSTRAINT ck_life_policy_detail_death_benefit_option CHECK (death_benefit_option IN ('LEVEL', 'INCREASING', 'RETURN_OF_PREMIUM')),
  premium_mode text NOT NULL CONSTRAINT ck_life_policy_detail_premium_mode CHECK (premium_mode IN ('ANNUAL', 'SEMI_ANNUAL', 'QUARTERLY', 'MONTHLY', 'BIWEEKLY', 'WEEKLY', 'SINGLE', 'FLEXIBLE')),
  modal_premium_amount numeric(18,2),
  planned_periodic_premium_amount numeric(18,2),
  level_term_period_years integer,
  issue_date date NOT NULL,
  maturity_date date,
  paid_to_date date,
  tax_qualification_type text CONSTRAINT ck_life_policy_detail_tax_qualification_type CHECK (tax_qualification_type IN ('NON_QUALIFIED', 'TRADITIONAL_IRA', 'ROTH_IRA', 'SEP_IRA', 'SIMPLE_IRA', 'INHERITED_IRA', 'PLAN_401K', 'PLAN_403B', 'PLAN_457', 'PENSION', 'QLAC')),
  is_participating boolean,
  dividend_option text CONSTRAINT ck_life_policy_detail_dividend_option CHECK (dividend_option IN ('CASH', 'PREMIUM_REDUCTION', 'ACCUMULATE_AT_INTEREST', 'PAID_UP_ADDITIONS', 'ONE_YEAR_TERM', 'LOAN_REDUCTION')),
  nonforfeiture_option text CONSTRAINT ck_life_policy_detail_nonforfeiture_option CHECK (nonforfeiture_option IN ('CASH_SURRENDER', 'REDUCED_PAID_UP', 'EXTENDED_TERM', 'AUTOMATIC_PREMIUM_LOAN')),
  is_modified_endowment_contract boolean,
  seven_pay_premium_amount numeric(18,2),
  guideline_single_premium_amount numeric(18,2),
  guideline_level_premium_amount numeric(18,2),
  definition_of_life_insurance_test varchar(10),
  contestability_end_date date,
  suicide_exclusion_end_date date,
  no_lapse_guarantee_end_date date,
  is_replacement boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_life_policy_detail PRIMARY KEY (policy_id)
);
COMMENT ON TABLE life_policy_detail IS 'Life insurance specific attributes of a policy.';

CREATE TABLE underwriting_case (
  underwriting_case_id uuid NOT NULL,
  submission_id uuid NOT NULL,
  insured_party_id uuid NOT NULL,
  underwriting_case_status text NOT NULL CONSTRAINT ck_underwriting_case_underwriting_case_status CHECK (underwriting_case_status IN ('OPEN', 'PENDING_REQUIREMENTS', 'IN_REVIEW', 'DECIDED', 'ISSUED', 'CLOSED_INCOMPLETE', 'WITHDRAWN')),
  requested_face_amount numeric(18,2),
  is_accelerated_underwriting boolean,
  underwriter_staff_member_id uuid,
  height_inches numeric(18,6),
  weight_pounds numeric(18,6),
  annual_income_amount numeric(18,2),
  net_worth_amount numeric(18,2),
  total_inforce_and_applied_amount numeric(18,2),
  approved_underwriting_class varchar(30),
  approved_table_rating varchar(5),
  underwriting_decision_id uuid,
  reinsurance_contract_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_underwriting_case PRIMARY KEY (underwriting_case_id)
);
COMMENT ON TABLE underwriting_case IS 'Medical and financial underwriting of one proposed insured for a life, disability or long-term care application.';

CREATE TABLE underwriting_requirement (
  underwriting_requirement_id uuid NOT NULL,
  underwriting_case_id uuid NOT NULL,
  requirement_code varchar(30) NOT NULL,
  requirement_status text NOT NULL CONSTRAINT ck_underwriting_requirement_requirement_status CHECK (requirement_status IN ('ORDERED', 'RECEIVED', 'REVIEWED', 'WAIVED', 'CANCELLED')),
  vendor_party_id uuid,
  ordered_on date,
  received_on date,
  result_summary text,
  result_document_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_underwriting_requirement PRIMARY KEY (underwriting_requirement_id)
);
COMMENT ON TABLE underwriting_requirement IS 'A piece of evidence ordered for an underwriting case: paramedical exam, labs, attending physician statement, MIB check, prescription history, MVR, inspection report, financial statement.';

CREATE TABLE benefit_accumulator (
  benefit_accumulator_id uuid NOT NULL,
  enrollment_id uuid NOT NULL,
  accumulator_type text NOT NULL CONSTRAINT ck_benefit_accumulator_accumulator_type CHECK (accumulator_type IN ('DEDUCTIBLE', 'OUT_OF_POCKET_MAXIMUM', 'BENEFIT_MAXIMUM', 'VISIT_LIMIT', 'LIFETIME_MAXIMUM')),
  accumulator_level text NOT NULL CONSTRAINT ck_benefit_accumulator_accumulator_level CHECK (accumulator_level IN ('INDIVIDUAL', 'FAMILY')),
  network_tier text NOT NULL CONSTRAINT ck_benefit_accumulator_network_tier CHECK (network_tier IN ('IN_NETWORK', 'PREFERRED', 'OUT_OF_NETWORK', 'ANY')),
  plan_benefit_id uuid,
  period_start_date date NOT NULL,
  period_end_date date NOT NULL,
  accumulated_amount numeric(18,6) NOT NULL,
  limit_amount numeric(18,6),
  last_health_claim_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_benefit_accumulator PRIMARY KEY (benefit_accumulator_id)
);
COMMENT ON TABLE benefit_accumulator IS 'Running total toward a deductible, out-of-pocket maximum or benefit limit for a member or family in a benefit period.';

CREATE TABLE coordination_of_benefits (
  coordination_of_benefits_id uuid NOT NULL,
  member_id uuid NOT NULL,
  other_carrier_name varchar(255) NOT NULL,
  other_carrier_insurer_id uuid,
  other_policy_number varchar(50),
  other_coverage_type varchar(30),
  payer_order integer NOT NULL,
  effective_date date NOT NULL,
  termination_date date,
  verified_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_coordination_of_benefits PRIMARY KEY (coordination_of_benefits_id)
);
COMMENT ON TABLE coordination_of_benefits IS 'Other health coverage a member holds, and the order in which payers are responsible.';

CREATE TABLE disability_claim_detail (
  claim_id uuid NOT NULL,
  disability_type text NOT NULL CONSTRAINT ck_disability_claim_detail_disability_type CHECK (disability_type IN ('SHORT_TERM', 'LONG_TERM', 'WAIVER_OF_PREMIUM', 'LONG_TERM_CARE', 'PAID_FAMILY_LEAVE')),
  claimant_party_id uuid NOT NULL,
  disability_date date NOT NULL,
  last_day_worked date,
  primary_diagnosis_code_value_id uuid,
  elimination_period_days integer,
  benefit_start_date date,
  maximum_benefit_end_date date,
  gross_benefit_amount numeric(18,2),
  benefit_frequency text CONSTRAINT ck_disability_claim_detail_benefit_frequency CHECK (benefit_frequency IN ('ANNUAL', 'SEMI_ANNUAL', 'QUARTERLY', 'MONTHLY', 'BIWEEKLY', 'WEEKLY', 'SINGLE', 'FLEXIBLE')),
  predisability_earnings_amount numeric(18,2),
  offset_amount numeric(18,2),
  own_occupation_end_date date,
  expected_return_to_work_date date,
  actual_return_to_work_date date,
  is_work_related boolean,
  ssdi_award_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_disability_claim_detail PRIMARY KEY (claim_id)
);
COMMENT ON TABLE disability_claim_detail IS 'Disability, long-term care and waiver specific attributes of a claim.';

CREATE TABLE employer_group (
  policy_id uuid NOT NULL,
  group_number varchar(30) NOT NULL,
  sponsor_party_id uuid NOT NULL,
  market_segment text NOT NULL CONSTRAINT ck_employer_group_market_segment CHECK (market_segment IN ('INDIVIDUAL', 'SMALL_GROUP', 'LARGE_GROUP', 'SELF_FUNDED', 'MEDICARE', 'MEDICAID', 'STUDENT', 'ASSOCIATION')),
  eligible_employee_count integer,
  enrolled_employee_count integer,
  new_hire_waiting_period_days integer,
  employer_contribution_percent numeric(9,4),
  plan_year_start_month integer,
  is_erisa_plan boolean,
  is_cobra_eligible boolean,
  funding_arrangement varchar(30),
  stop_loss_specific_attachment_amount numeric(18,2),
  stop_loss_aggregate_attachment_percent numeric(9,4),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_employer_group PRIMARY KEY (policy_id)
);
COMMENT ON TABLE employer_group IS 'Group-specific attributes of a group master policy: the employer or association sponsoring coverage for its members.';

CREATE TABLE enrollment (
  enrollment_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  health_plan_id uuid NOT NULL,
  member_id uuid NOT NULL,
  subscriber_member_id uuid NOT NULL,
  member_relationship text NOT NULL CONSTRAINT ck_enrollment_member_relationship CHECK (member_relationship IN ('SELF', 'SPOUSE', 'DOMESTIC_PARTNER', 'CHILD', 'DISABLED_DEPENDENT', 'OTHER_DEPENDENT')),
  coverage_tier text CONSTRAINT ck_enrollment_coverage_tier CHECK (coverage_tier IN ('EMPLOYEE_ONLY', 'EMPLOYEE_SPOUSE', 'EMPLOYEE_CHILDREN', 'FAMILY', 'INDIVIDUAL', 'CHILD_ONLY')),
  group_subgroup_id uuid,
  enrollment_status text NOT NULL CONSTRAINT ck_enrollment_enrollment_status CHECK (enrollment_status IN ('PENDING', 'ACTIVE', 'TERMINATED', 'CANCELLED', 'COBRA', 'GRACE_PERIOD')),
  effective_date date NOT NULL,
  termination_date date,
  termination_reason varchar(50),
  enrollment_source varchar(30),
  qualifying_event varchar(50),
  primary_care_provider_id uuid,
  exchange_subscriber_id varchar(30),
  paid_through_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_enrollment PRIMARY KEY (enrollment_id)
);
COMMENT ON TABLE enrollment IS 'A span of a member''s coverage in a plan under a policy (individual policy or group master). Subscribers and dependents each have their own spans; dependents point to the subscriber.';

CREATE TABLE enrollment_rate (
  enrollment_rate_id uuid NOT NULL,
  enrollment_id uuid NOT NULL,
  effective_date date NOT NULL,
  end_date date,
  monthly_premium_amount numeric(18,2) NOT NULL,
  employer_contribution_amount numeric(18,2),
  member_contribution_amount numeric(18,2),
  advance_premium_tax_credit_amount numeric(18,2),
  rating_area varchar(20),
  rated_age integer,
  tobacco_surcharge_amount numeric(18,2),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_enrollment_rate PRIMARY KEY (enrollment_rate_id)
);
COMMENT ON TABLE enrollment_rate IS 'Premium rate for an enrollment over a period, with its split between employer, member and subsidy.';

CREATE TABLE group_subgroup (
  group_subgroup_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  subgroup_code varchar(30) NOT NULL,
  name varchar(255) NOT NULL,
  eligibility_class varchar(50),
  billing_account_id uuid,
  effective_date date NOT NULL,
  termination_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_group_subgroup PRIMARY KEY (group_subgroup_id),
  CONSTRAINT uq_group_subgroup_policy_id_subgroup_code UNIQUE (policy_id, subgroup_code)
);
COMMENT ON TABLE group_subgroup IS 'A division, class or billing unit within an employer group, with the plans offered to it.';

CREATE TABLE health_claim (
  health_claim_id uuid NOT NULL,
  claim_number varchar(30) NOT NULL,
  health_claim_type text NOT NULL CONSTRAINT ck_health_claim_health_claim_type CHECK (health_claim_type IN ('PROFESSIONAL', 'INSTITUTIONAL', 'DENTAL', 'PHARMACY', 'VISION', 'MEMBER_REIMBURSEMENT')),
  health_claim_status text NOT NULL CONSTRAINT ck_health_claim_health_claim_status CHECK (health_claim_status IN ('RECEIVED', 'PENDED', 'IN_REVIEW', 'ADJUDICATED', 'PAID', 'DENIED', 'PARTIALLY_DENIED', 'ADJUSTED', 'REVERSED', 'VOIDED')),
  enrollment_id uuid NOT NULL,
  billing_provider_id uuid,
  rendering_provider_id uuid,
  facility_provider_id uuid,
  referring_provider_id uuid,
  network_tier text CONSTRAINT ck_health_claim_network_tier CHECK (network_tier IN ('IN_NETWORK', 'PREFERRED', 'OUT_OF_NETWORK', 'ANY')),
  received_date date NOT NULL,
  service_from_date date NOT NULL,
  service_to_date date,
  admission_date date,
  discharge_date date,
  type_of_bill varchar(4),
  place_of_service_code varchar(2),
  drg_code_value_id uuid,
  discharge_status_code varchar(2),
  claim_frequency_code varchar(1),
  replaces_health_claim_id uuid,
  prior_authorization_id uuid,
  submitter_claim_id varchar(50),
  billed_amount numeric(18,2) NOT NULL,
  allowed_amount numeric(18,2),
  paid_amount numeric(18,2),
  member_responsibility_amount numeric(18,2),
  other_payer_paid_amount numeric(18,2),
  adjudicated_at timestamptz,
  accounting_date date,
  is_accident_related boolean,
  accident_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_health_claim PRIMARY KEY (health_claim_id),
  CONSTRAINT uq_health_claim_claim_number UNIQUE (claim_number)
);
COMMENT ON TABLE health_claim IS 'A claim for health care services submitted by a provider or member, as adjudicated. Adjustments are new claims that point to the claim they replace.';

CREATE TABLE health_claim_diagnosis (
  health_claim_diagnosis_id uuid NOT NULL,
  health_claim_id uuid NOT NULL,
  sequence_number integer NOT NULL,
  diagnosis_code_value_id uuid NOT NULL,
  diagnosis_qualifier text NOT NULL CONSTRAINT ck_health_claim_diagnosis_diagnosis_qualifier CHECK (diagnosis_qualifier IN ('PRINCIPAL', 'ADMITTING', 'SECONDARY', 'EXTERNAL_CAUSE', 'PATIENT_REASON_FOR_VISIT')),
  present_on_admission varchar(1),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_health_claim_diagnosis PRIMARY KEY (health_claim_diagnosis_id),
  CONSTRAINT uq_health_claim_diagnosis_health_claim_id_sequence_number UNIQUE (health_claim_id, sequence_number)
);
COMMENT ON TABLE health_claim_diagnosis IS 'A diagnosis reported on a health claim.';

CREATE TABLE health_claim_line (
  health_claim_line_id uuid NOT NULL,
  health_claim_id uuid NOT NULL,
  line_number integer NOT NULL,
  claim_line_status text NOT NULL CONSTRAINT ck_health_claim_line_claim_line_status CHECK (claim_line_status IN ('PENDED', 'APPROVED', 'DENIED', 'ADJUSTED')),
  service_from_date date NOT NULL,
  service_to_date date,
  procedure_code_value_id uuid,
  modifier_1 varchar(2),
  modifier_2 varchar(2),
  modifier_3 varchar(2),
  modifier_4 varchar(2),
  revenue_code varchar(4),
  ndc_code varchar(11),
  tooth_number varchar(5),
  place_of_service_code varchar(2),
  diagnosis_pointers varchar(20),
  rendering_provider_id uuid,
  plan_benefit_id uuid,
  units numeric(18,6),
  days_supply integer,
  billed_amount numeric(18,2) NOT NULL,
  allowed_amount numeric(18,2),
  not_covered_amount numeric(18,2),
  deductible_amount numeric(18,2),
  copay_amount numeric(18,2),
  coinsurance_amount numeric(18,2),
  other_payer_paid_amount numeric(18,2),
  paid_amount numeric(18,2),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_health_claim_line PRIMARY KEY (health_claim_line_id),
  CONSTRAINT uq_health_claim_line_health_claim_id_line_number UNIQUE (health_claim_id, line_number)
);
COMMENT ON TABLE health_claim_line IS 'A service line of a health claim with its adjudicated amounts.';

CREATE TABLE health_claim_line_adjustment (
  health_claim_line_adjustment_id uuid NOT NULL,
  health_claim_line_id uuid NOT NULL,
  adjustment_group_code varchar(2) NOT NULL,
  reason_code_value_id uuid NOT NULL,
  remark_code_value_id uuid,
  amount numeric(18,2) NOT NULL,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_health_claim_line_adjustment PRIMARY KEY (health_claim_line_adjustment_id)
);
COMMENT ON TABLE health_claim_line_adjustment IS 'A reason-coded difference between billed and paid amounts on a claim line (X12 835 CAS adjustment).';

CREATE TABLE health_claim_payment (
  health_claim_payment_id uuid NOT NULL,
  health_claim_id uuid NOT NULL,
  disbursement_id uuid NOT NULL,
  amount numeric(18,2) NOT NULL,
  interest_amount numeric(18,2),
  is_paid_to_member boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_health_claim_payment PRIMARY KEY (health_claim_payment_id)
);
COMMENT ON TABLE health_claim_payment IS 'Portion of a disbursement (remittance) that pays a health claim.';

CREATE TABLE health_plan (
  health_plan_id uuid NOT NULL,
  product_id uuid NOT NULL,
  plan_code varchar(30) NOT NULL,
  plan_year integer NOT NULL,
  name varchar(255) NOT NULL,
  health_plan_type text NOT NULL CONSTRAINT ck_health_plan_health_plan_type CHECK (health_plan_type IN ('HMO', 'PPO', 'EPO', 'POS', 'HDHP', 'INDEMNITY', 'DENTAL_PPO', 'DENTAL_HMO', 'VISION', 'MEDICARE_SUPPLEMENT', 'MEDICARE_ADVANTAGE', 'PART_D', 'SHORT_TERM_DISABILITY', 'LONG_TERM_DISABILITY', 'LONG_TERM_CARE', 'ACCIDENT', 'CRITICAL_ILLNESS', 'HOSPITAL_INDEMNITY')),
  market_segment text NOT NULL CONSTRAINT ck_health_plan_market_segment CHECK (market_segment IN ('INDIVIDUAL', 'SMALL_GROUP', 'LARGE_GROUP', 'SELF_FUNDED', 'MEDICARE', 'MEDICAID', 'STUDENT', 'ASSOCIATION')),
  metal_tier text CONSTRAINT ck_health_plan_metal_tier CHECK (metal_tier IN ('CATASTROPHIC', 'BRONZE', 'SILVER', 'GOLD', 'PLATINUM', 'NOT_APPLICABLE')),
  hios_plan_id varchar(20),
  cms_contract_number varchar(20),
  provider_network_id uuid,
  individual_deductible_amount numeric(18,2),
  family_deductible_amount numeric(18,2),
  individual_out_of_pocket_max_amount numeric(18,2),
  family_out_of_pocket_max_amount numeric(18,2),
  is_hsa_eligible boolean,
  actuarial_value_percent numeric(9,4),
  accumulator_period varchar(20),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_health_plan PRIMARY KEY (health_plan_id),
  CONSTRAINT uq_health_plan_plan_code_plan_year UNIQUE (plan_code, plan_year)
);
COMMENT ON TABLE health_plan IS 'A benefit plan design offered under a health product for a plan year.';

CREATE TABLE member (
  member_id uuid NOT NULL,
  party_id uuid NOT NULL,
  member_number varchar(30) NOT NULL,
  medicare_eligibility_reason varchar(20),
  is_tobacco_user boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_member PRIMARY KEY (member_id),
  CONSTRAINT uq_member_member_number UNIQUE (member_number)
);
COMMENT ON TABLE member IS 'A person covered or formerly covered by health or group benefits, identified by a member ID.';

CREATE TABLE network_participation (
  network_participation_id uuid NOT NULL,
  provider_network_id uuid NOT NULL,
  provider_id uuid NOT NULL,
  practice_address_id uuid,
  network_tier text CONSTRAINT ck_network_participation_network_tier CHECK (network_tier IN ('IN_NETWORK', 'PREFERRED', 'OUT_OF_NETWORK', 'ANY')),
  contract_number varchar(50),
  reimbursement_method varchar(30),
  reimbursement_percent numeric(9,4),
  fee_schedule_code varchar(30),
  effective_date date NOT NULL,
  termination_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_network_participation PRIMARY KEY (network_participation_id)
);
COMMENT ON TABLE network_participation IS 'Participation of a provider in a network at a practice location over a period, with the reimbursement arrangement.';

CREATE TABLE plan_benefit (
  plan_benefit_id uuid NOT NULL,
  health_plan_id uuid NOT NULL,
  benefit_code varchar(30) NOT NULL,
  name varchar(255) NOT NULL,
  network_tier text NOT NULL CONSTRAINT ck_plan_benefit_network_tier CHECK (network_tier IN ('IN_NETWORK', 'PREFERRED', 'OUT_OF_NETWORK', 'ANY')),
  is_covered boolean NOT NULL,
  copay_amount numeric(18,2),
  coinsurance_percent numeric(9,4),
  deductible_applies boolean,
  limit_quantity numeric(18,6),
  limit_unit varchar(20),
  limit_period text CONSTRAINT ck_plan_benefit_limit_period CHECK (limit_period IN ('PER_OCCURRENCE', 'PER_CLAIM', 'PER_PERSON', 'PER_ACCIDENT', 'PER_ITEM', 'PER_LOCATION', 'PER_DAY', 'PER_WEEK', 'PER_MONTH', 'PER_VISIT', 'AGGREGATE', 'POLICY_PERIOD', 'CALENDAR_YEAR', 'LIFETIME', 'NOT_APPLICABLE')),
  requires_prior_authorization boolean,
  requires_referral boolean,
  waiting_period_days integer,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_plan_benefit PRIMARY KEY (plan_benefit_id),
  CONSTRAINT uq_plan_benefit_health_plan_id_benefit_code_network_tier UNIQUE (health_plan_id, benefit_code, network_tier)
);
COMMENT ON TABLE plan_benefit IS 'Cost sharing and limits for a category of service under a plan and network tier.';

CREATE TABLE prior_authorization (
  prior_authorization_id uuid NOT NULL,
  authorization_number varchar(30) NOT NULL,
  enrollment_id uuid NOT NULL,
  requesting_provider_id uuid,
  servicing_provider_id uuid,
  authorization_status text NOT NULL CONSTRAINT ck_prior_authorization_authorization_status CHECK (authorization_status IN ('REQUESTED', 'PENDED', 'APPROVED', 'PARTIALLY_APPROVED', 'DENIED', 'WITHDRAWN', 'EXPIRED')),
  service_type varchar(50),
  is_urgent boolean,
  procedure_code_value_id uuid,
  diagnosis_code_value_id uuid,
  requested_units numeric(18,6),
  approved_units numeric(18,6),
  requested_at timestamptz NOT NULL,
  decided_at timestamptz,
  valid_from date,
  valid_to date,
  denial_reason varchar(200),
  reviewer_staff_member_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_prior_authorization PRIMARY KEY (prior_authorization_id),
  CONSTRAINT uq_prior_authorization_authorization_number UNIQUE (authorization_number)
);
COMMENT ON TABLE prior_authorization IS 'A request for approval of services before they are rendered, and the utilization management decision.';

CREATE TABLE provider (
  provider_id uuid NOT NULL,
  party_id uuid NOT NULL,
  npi varchar(10),
  provider_type text NOT NULL CONSTRAINT ck_provider_provider_type CHECK (provider_type IN ('INDIVIDUAL_PRACTITIONER', 'GROUP_PRACTICE', 'HOSPITAL', 'AMBULATORY_FACILITY', 'SKILLED_NURSING', 'HOME_HEALTH', 'PHARMACY', 'LABORATORY', 'DME_SUPPLIER', 'DENTAL', 'VISION', 'BEHAVIORAL_HEALTH', 'OTHER')),
  taxonomy_code_value_id uuid,
  specialty varchar(100),
  billing_group_provider_id uuid,
  credentialed_on date,
  recredential_due_on date,
  is_accepting_new_patients boolean,
  is_sanctioned boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_provider PRIMARY KEY (provider_id)
);
COMMENT ON TABLE provider IS 'A health care practitioner, group or facility that renders or bills services.';

CREATE TABLE provider_network (
  provider_network_id uuid NOT NULL,
  network_code varchar(30) NOT NULL,
  name varchar(255) NOT NULL,
  network_type varchar(30),
  is_leased boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_provider_network PRIMARY KEY (provider_network_id),
  CONSTRAINT uq_provider_network_network_code UNIQUE (network_code)
);
COMMENT ON TABLE provider_network IS 'A contracted network of providers that plans use to define in-network benefits.';

CREATE TABLE catastrophe_event (
  catastrophe_event_id uuid NOT NULL,
  catastrophe_code varchar(30) NOT NULL,
  pcs_serial_number varchar(20),
  name varchar(255) NOT NULL,
  cause_of_loss_code varchar(30),
  start_date date NOT NULL,
  end_date date,
  affected_jurisdictions varchar(500),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_catastrophe_event PRIMARY KEY (catastrophe_event_id),
  CONSTRAINT uq_catastrophe_event_catastrophe_code UNIQUE (catastrophe_code)
);
COMMENT ON TABLE catastrophe_event IS 'A catastrophe to which many claims are attributed, such as a named hurricane, wildfire or hailstorm.';

CREATE TABLE claim (
  claim_id uuid NOT NULL,
  claim_number varchar(30) NOT NULL,
  policy_id uuid,
  policy_term_id uuid,
  line_of_business_code varchar(30),
  claim_status text NOT NULL CONSTRAINT ck_claim_claim_status CHECK (claim_status IN ('DRAFT', 'OPEN', 'CLOSED', 'REOPENED', 'DENIED', 'WITHDRAWN', 'VOIDED')),
  loss_at timestamptz NOT NULL,
  loss_date_is_estimated boolean,
  reported_at timestamptz NOT NULL,
  claims_made_date date,
  fnol_channel text CONSTRAINT ck_claim_fnol_channel CHECK (fnol_channel IN ('PHONE', 'WEB', 'MOBILE_APP', 'AGENT', 'EMAIL', 'MAIL', 'TELEMATICS', 'EDI', 'THIRD_PARTY_ADMINISTRATOR')),
  cause_of_loss_code varchar(30),
  loss_description text,
  loss_address_id uuid,
  loss_jurisdiction_code varchar(6),
  catastrophe_event_id uuid,
  coverage_verification_status text CONSTRAINT ck_claim_coverage_verification_status CHECK (coverage_verification_status IN ('PENDING', 'CONFIRMED', 'RESERVATION_OF_RIGHTS', 'DENIED', 'PARTIAL')),
  insured_fault_percent numeric(9,4),
  police_report_number varchar(50),
  is_in_litigation boolean,
  is_large_loss boolean,
  handling_office_code varchar(30),
  third_party_administrator_party_id uuid,
  closed_at timestamptz,
  reopened_at timestamptz,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim PRIMARY KEY (claim_id),
  CONSTRAINT uq_claim_claim_number UNIQUE (claim_number)
);
COMMENT ON TABLE claim IS 'A demand for benefits arising from one loss occurrence under one policy. Supertype for line-specific claim detail.';

CREATE TABLE claim_assignment (
  claim_assignment_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  claim_exposure_id uuid,
  staff_member_id uuid NOT NULL,
  claim_assignment_role text NOT NULL CONSTRAINT ck_claim_assignment_claim_assignment_role CHECK (claim_assignment_role IN ('OWNER', 'FIELD_ADJUSTER', 'INJURY_ADJUSTER', 'PROPERTY_ADJUSTER', 'TOTAL_LOSS', 'SUBROGATION', 'SIU', 'LITIGATION', 'NURSE_CASE_MANAGER', 'SUPERVISOR')),
  assigned_at timestamptz NOT NULL,
  unassigned_at timestamptz,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_assignment PRIMARY KEY (claim_assignment_id)
);
COMMENT ON TABLE claim_assignment IS 'Assignment of a staff member to a claim or exposure over a period.';

CREATE TABLE claim_exposure (
  claim_exposure_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  exposure_number integer NOT NULL,
  claimant_claim_party_id uuid NOT NULL,
  policy_coverage_id uuid,
  coverage_definition_id uuid NOT NULL,
  claim_incident_id uuid,
  exposure_status text NOT NULL CONSTRAINT ck_claim_exposure_exposure_status CHECK (exposure_status IN ('DRAFT', 'OPEN', 'CLOSED', 'REOPENED', 'DENIED', 'WITHDRAWN', 'VOIDED')),
  jurisdiction_code varchar(6),
  asl_code varchar(10),
  is_first_party boolean,
  deductible_applied_amount numeric(18,2),
  denial_reason varchar(200),
  opened_at timestamptz NOT NULL,
  closed_at timestamptz,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_exposure PRIMARY KEY (claim_exposure_id),
  CONSTRAINT uq_claim_exposure_claim_id_exposure_number UNIQUE (claim_id, exposure_number)
);
COMMENT ON TABLE claim_exposure IS 'One claimant''s claim under one coverage (also called a feature or sub-claim). The level at which reserves are set, payments are made and losses are reported by coverage and statutory line.';

CREATE TABLE claim_financial_transaction (
  claim_financial_transaction_id uuid NOT NULL,
  claim_exposure_id uuid NOT NULL,
  claim_transaction_type text NOT NULL CONSTRAINT ck_claim_financial_transaction_claim_transaction_type CHECK (claim_transaction_type IN ('RESERVE', 'PAYMENT', 'RECOVERY_RESERVE', 'RECOVERY')),
  claim_cost_category text NOT NULL CONSTRAINT ck_claim_financial_transaction_claim_cost_category CHECK (claim_cost_category IN ('INDEMNITY', 'MEDICAL', 'DEFENSE_COST_CONTAINMENT', 'ADJUSTING_OTHER')),
  cost_type_code varchar(50),
  amount numeric(18,2) NOT NULL,
  transaction_at timestamptz NOT NULL,
  accounting_date date NOT NULL,
  claim_payment_id uuid,
  claim_recovery_id uuid,
  reverses_transaction_id uuid,
  service_from_date date,
  service_to_date date,
  entered_by_staff_member_id uuid,
  comment varchar(500),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_financial_transaction PRIMARY KEY (claim_financial_transaction_id)
);
COMMENT ON TABLE claim_financial_transaction IS 'The claim ledger: every reserve change, payment and recovery as a signed amount by exposure and cost category. Paid, outstanding and incurred amounts as of any date are sums over this entity.';

CREATE TABLE claim_incident (
  claim_incident_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  claim_incident_type text NOT NULL CONSTRAINT ck_claim_incident_claim_incident_type CHECK (claim_incident_type IN ('VEHICLE_DAMAGE', 'PROPERTY_DAMAGE', 'CONTENTS_LOSS', 'BODILY_INJURY', 'DEATH', 'LOSS_OF_USE', 'BUSINESS_INTERRUPTION', 'FINANCIAL_LOSS', 'DATA_BREACH', 'OTHER')),
  policy_risk_id uuid,
  insurable_object_id uuid,
  injured_claim_party_id uuid,
  owner_claim_party_id uuid,
  description text,
  damage_estimate_amount numeric(18,2),
  is_total_loss boolean,
  is_drivable boolean,
  point_of_impact varchar(50),
  injury_severity text CONSTRAINT ck_claim_incident_injury_severity CHECK (injury_severity IN ('NONE', 'MINOR', 'MODERATE', 'SERIOUS', 'SEVERE', 'CATASTROPHIC', 'FATAL')),
  injury_description text,
  body_part_code_value_id uuid,
  nature_of_injury_code_value_id uuid,
  received_medical_treatment boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_incident PRIMARY KEY (claim_incident_id)
);
COMMENT ON TABLE claim_incident IS 'One thing that was lost or damaged, or one person who was injured, in the occurrence: a damaged vehicle, a burned building, an injured passenger.';

CREATE TABLE claim_investigation (
  claim_investigation_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  investigation_status text NOT NULL CONSTRAINT ck_claim_investigation_investigation_status CHECK (investigation_status IN ('REFERRED', 'ACCEPTED', 'IN_PROGRESS', 'CLOSED_FRAUD_CONFIRMED', 'CLOSED_NO_FRAUD', 'CLOSED_INCONCLUSIVE', 'DECLINED')),
  referral_source varchar(30),
  fraud_score numeric(18,6),
  indicators text,
  investigator_staff_member_id uuid,
  referred_on date NOT NULL,
  closed_on date,
  reported_to_authorities_on date,
  savings_amount numeric(18,2),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_investigation PRIMARY KEY (claim_investigation_id)
);
COMMENT ON TABLE claim_investigation IS 'A special investigation of suspected fraud on a claim.';

CREATE TABLE claim_litigation (
  claim_litigation_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  claim_exposure_id uuid,
  litigation_status text NOT NULL CONSTRAINT ck_claim_litigation_litigation_status CHECK (litigation_status IN ('PRE_SUIT', 'FILED', 'DISCOVERY', 'MEDIATION', 'TRIAL', 'APPEAL', 'SETTLED', 'JUDGMENT', 'DISMISSED', 'CLOSED')),
  case_number varchar(50),
  court_name varchar(255),
  venue_jurisdiction_code varchar(6),
  caption varchar(500),
  plaintiff_attorney_claim_party_id uuid,
  defense_attorney_claim_party_id uuid,
  filed_on date,
  served_on date,
  trial_date date,
  demand_amount numeric(18,2),
  offer_amount numeric(18,2),
  resolution_amount numeric(18,2),
  resolved_on date,
  is_coverage_litigation boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_litigation PRIMARY KEY (claim_litigation_id)
);
COMMENT ON TABLE claim_litigation IS 'A lawsuit or other legal proceeding connected to a claim.';

CREATE TABLE claim_note (
  claim_note_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  claim_exposure_id uuid,
  topic varchar(50),
  note_text text NOT NULL,
  author_staff_member_id uuid,
  written_at timestamptz NOT NULL,
  is_confidential boolean,
  follow_up_due_on date,
  follow_up_completed_at timestamptz,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_note PRIMARY KEY (claim_note_id)
);
COMMENT ON TABLE claim_note IS 'A file note or diary entry on a claim.';

CREATE TABLE claim_party (
  claim_party_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  party_id uuid NOT NULL,
  claim_party_role text NOT NULL CONSTRAINT ck_claim_party_claim_party_role CHECK (claim_party_role IN ('INSURED', 'CLAIMANT', 'REPORTER', 'INSURED_DRIVER', 'OTHER_DRIVER', 'PASSENGER', 'PEDESTRIAN', 'INJURED_WORKER', 'EMPLOYER', 'WITNESS', 'PROPERTY_OWNER', 'BENEFICIARY', 'CLAIMANT_ATTORNEY', 'DEFENSE_ATTORNEY', 'OTHER_CARRIER', 'MEDICAL_PROVIDER', 'REPAIR_FACILITY', 'RENTAL_AGENCY', 'CONTRACTOR', 'INDEPENDENT_ADJUSTER', 'APPRAISER', 'EXPERT', 'LIENHOLDER', 'PUBLIC_ADJUSTER', 'OTHER_VENDOR')),
  represented_by_claim_party_id uuid,
  other_carrier_claim_number varchar(50),
  is_medicare_beneficiary boolean,
  notes text,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_party PRIMARY KEY (claim_party_id)
);
COMMENT ON TABLE claim_party IS 'A party involved in a claim in a given role.';

CREATE TABLE claim_payment (
  claim_payment_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  claim_payment_type text NOT NULL CONSTRAINT ck_claim_payment_claim_payment_type CHECK (claim_payment_type IN ('PARTIAL', 'FINAL', 'SUPPLEMENTAL', 'ADVANCE', 'RECURRING')),
  claim_payment_status text NOT NULL CONSTRAINT ck_claim_payment_claim_payment_status CHECK (claim_payment_status IN ('REQUESTED', 'PENDING_APPROVAL', 'APPROVED', 'ISSUED', 'CLEARED', 'VOIDED', 'STOPPED', 'REJECTED')),
  amount numeric(18,2) NOT NULL,
  disbursement_id uuid,
  requested_by_staff_member_id uuid,
  approved_by_staff_member_id uuid,
  requested_at timestamptz NOT NULL,
  approved_at timestamptz,
  invoice_number varchar(50),
  memo varchar(500),
  is_tax_reportable boolean,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_payment PRIMARY KEY (claim_payment_id)
);
COMMENT ON TABLE claim_payment IS 'A payment issued on a claim to one or more payees. Its allocation to exposures and cost categories is in the claim ledger; the instrument is a disbursement.';

CREATE TABLE claim_payment_payee (
  claim_payment_payee_id uuid NOT NULL,
  claim_payment_id uuid NOT NULL,
  party_id uuid NOT NULL,
  is_primary_payee boolean NOT NULL,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_payment_payee PRIMARY KEY (claim_payment_payee_id),
  CONSTRAINT uq_claim_payment_payee_claim_payment_id_party_id UNIQUE (claim_payment_id, party_id)
);
COMMENT ON TABLE claim_payment_payee IS 'A payee named on a claim payment.';

CREATE TABLE claim_recovery (
  claim_recovery_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  claim_recovery_type text NOT NULL CONSTRAINT ck_claim_recovery_claim_recovery_type CHECK (claim_recovery_type IN ('SUBROGATION', 'SALVAGE', 'DEDUCTIBLE', 'CONTRIBUTION', 'SECOND_INJURY_FUND', 'OVERPAYMENT', 'RESTITUTION', 'OTHER')),
  recovery_status text NOT NULL CONSTRAINT ck_claim_recovery_recovery_status CHECK (recovery_status IN ('IDENTIFIED', 'DEMAND_SENT', 'NEGOTIATION', 'ARBITRATION', 'LITIGATION', 'COLLECTED', 'CLOSED_NO_RECOVERY')),
  from_party_id uuid,
  adverse_fault_percent numeric(9,4),
  demand_amount numeric(18,2),
  demand_sent_on date,
  statute_of_limitations_date date,
  arbitration_forum_reference varchar(50),
  recovery_vendor_party_id uuid,
  closed_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_claim_recovery PRIMARY KEY (claim_recovery_id)
);
COMMENT ON TABLE claim_recovery IS 'An effort to recover claim costs from a responsible third party, salvage, the insured''s deductible or another source.';

CREATE TABLE workers_comp_claim_detail (
  claim_id uuid NOT NULL,
  wc_claim_type text NOT NULL CONSTRAINT ck_workers_comp_claim_detail_wc_claim_type CHECK (wc_claim_type IN ('MEDICAL_ONLY', 'TEMPORARY_TOTAL', 'TEMPORARY_PARTIAL', 'PERMANENT_PARTIAL', 'PERMANENT_TOTAL', 'FATALITY', 'REPORT_ONLY')),
  injured_worker_party_id uuid NOT NULL,
  jurisdiction_claim_number varchar(50),
  benefit_jurisdiction_code varchar(6),
  employer_notified_on date,
  class_code_value_id uuid,
  cause_of_injury_code_value_id uuid,
  hire_date date,
  occupation varchar(255),
  average_weekly_wage_amount numeric(18,2),
  compensation_rate_amount numeric(18,2),
  first_day_of_disability date,
  return_to_work_date date,
  is_modified_duty boolean,
  maximum_medical_improvement_date date,
  impairment_rating_percent numeric(9,4),
  is_compensability_accepted boolean,
  first_report_of_injury_filed_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_workers_comp_claim_detail PRIMARY KEY (claim_id)
);
COMMENT ON TABLE workers_comp_claim_detail IS 'Workers'' compensation specific attributes of a claim.';

CREATE TABLE billing_account (
  billing_account_id uuid NOT NULL,
  account_number varchar(30) NOT NULL,
  payor_party_id uuid NOT NULL,
  bill_method text NOT NULL CONSTRAINT ck_billing_account_bill_method CHECK (bill_method IN ('DIRECT_BILL', 'AGENCY_BILL', 'LIST_BILL', 'PAYROLL_DEDUCTION', 'MORTGAGEE_BILL', 'PAY_AS_YOU_GO', 'PREMIUM_FINANCE')),
  billing_account_status text NOT NULL CONSTRAINT ck_billing_account_billing_account_status CHECK (billing_account_status IN ('ACTIVE', 'DELINQUENT', 'SUSPENDED', 'COLLECTIONS', 'CLOSED')),
  currency_code varchar(3) NOT NULL,
  producer_id uuid,
  billing_address_id uuid,
  preferred_due_day integer,
  is_paperless boolean,
  autopay_payment_instrument_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_billing_account PRIMARY KEY (billing_account_id),
  CONSTRAINT uq_billing_account_account_number UNIQUE (account_number)
);
COMMENT ON TABLE billing_account IS 'An account through which a payor is billed for one or more policies.';

CREATE TABLE billing_account_policy (
  billing_account_policy_id uuid NOT NULL,
  billing_account_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  payment_plan_id uuid,
  effective_date date NOT NULL,
  end_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_billing_account_policy PRIMARY KEY (billing_account_policy_id)
);
COMMENT ON TABLE billing_account_policy IS 'Assignment of a policy to a billing account and payment plan over a period.';

CREATE TABLE billing_adjustment (
  billing_adjustment_id uuid NOT NULL,
  billing_account_id uuid NOT NULL,
  policy_id uuid,
  invoice_line_id uuid,
  billing_adjustment_type text NOT NULL CONSTRAINT ck_billing_adjustment_billing_adjustment_type CHECK (billing_adjustment_type IN ('WRITE_OFF', 'FEE_WAIVER', 'LATE_FEE', 'NSF_FEE', 'REINSTATEMENT_FEE', 'SMALL_BALANCE', 'TRANSFER', 'CREDIT')),
  amount numeric(18,2) NOT NULL,
  adjusted_at timestamptz NOT NULL,
  accounting_date date,
  reason varchar(200),
  approved_by_staff_member_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_billing_adjustment PRIMARY KEY (billing_adjustment_id)
);
COMMENT ON TABLE billing_adjustment IS 'A non-cash change to what a billing account owes: write-off, waived or assessed fee, transfer.';

CREATE TABLE commission_statement (
  commission_statement_id uuid NOT NULL,
  producer_id uuid NOT NULL,
  period_start_date date NOT NULL,
  period_end_date date NOT NULL,
  total_amount numeric(18,2) NOT NULL,
  disbursement_id uuid,
  issued_on date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_commission_statement PRIMARY KEY (commission_statement_id)
);
COMMENT ON TABLE commission_statement IS 'Periodic statement of commissions earned by and payable to a producer.';

CREATE TABLE commission_transaction (
  commission_transaction_id uuid NOT NULL,
  producer_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  premium_transaction_id uuid,
  payment_application_id uuid,
  commission_schedule_id uuid,
  commission_transaction_type text NOT NULL CONSTRAINT ck_commission_transaction_commission_transaction_type CHECK (commission_transaction_type IN ('EARNED', 'CHARGEBACK', 'ADVANCE', 'ADVANCE_RECOVERY', 'BONUS', 'ADJUSTMENT')),
  commission_basis text CONSTRAINT ck_commission_transaction_commission_basis CHECK (commission_basis IN ('NEW_BUSINESS', 'RENEWAL', 'FIRST_YEAR', 'TRAIL', 'OVERRIDE', 'CONTINGENT', 'BONUS')),
  commissionable_premium_amount numeric(18,2),
  commission_percent numeric(9,4),
  amount numeric(18,2) NOT NULL,
  accounting_date date NOT NULL,
  commission_statement_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_commission_transaction PRIMARY KEY (commission_transaction_id)
);
COMMENT ON TABLE commission_transaction IS 'Commission earned or charged back for a producer on a premium transaction or payment.';

CREATE TABLE delinquency_event (
  delinquency_event_id uuid NOT NULL,
  billing_account_id uuid NOT NULL,
  policy_id uuid,
  delinquency_event_type text NOT NULL CONSTRAINT ck_delinquency_event_delinquency_event_type CHECK (delinquency_event_type IN ('PAST_DUE_NOTICE', 'NOTICE_OF_CANCELLATION', 'GRACE_PERIOD_START', 'CANCELLATION_REQUESTED', 'LAPSE_NOTICE', 'COLLECTIONS_REFERRAL', 'CURED')),
  event_date date NOT NULL,
  past_due_amount numeric(18,2),
  cure_by_date date,
  notice_document_id uuid,
  policy_transaction_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_delinquency_event PRIMARY KEY (delinquency_event_id)
);
COMMENT ON TABLE delinquency_event IS 'A step in handling a past-due account, such as a notice of cancellation for non-payment.';

CREATE TABLE disbursement (
  disbursement_id uuid NOT NULL,
  disbursement_type text NOT NULL CONSTRAINT ck_disbursement_disbursement_type CHECK (disbursement_type IN ('CLAIM_PAYMENT', 'PREMIUM_REFUND', 'COMMISSION', 'ANNUITY_PAYOUT', 'CONTRACT_WITHDRAWAL', 'LOAN_PROCEEDS', 'DIVIDEND', 'PROVIDER_REMITTANCE', 'REINSURANCE_SETTLEMENT', 'VENDOR_PAYMENT', 'ESCHEATMENT')),
  disbursement_status text NOT NULL CONSTRAINT ck_disbursement_disbursement_status CHECK (disbursement_status IN ('PENDING', 'ISSUED', 'CLEARED', 'VOIDED', 'STOPPED', 'RETURNED', 'STALE_DATED', 'ESCHEATED')),
  payee_party_id uuid NOT NULL,
  payee_name_printed varchar(500),
  payment_method text NOT NULL CONSTRAINT ck_disbursement_payment_method CHECK (payment_method IN ('ACH', 'CREDIT_CARD', 'DEBIT_CARD', 'CHECK', 'WIRE', 'CASH', 'LOCKBOX', 'DIGITAL_WALLET', 'VIRTUAL_CARD', 'PUSH_TO_DEBIT', 'INTERNAL_TRANSFER')),
  payment_instrument_id uuid,
  mailing_address_id uuid,
  amount numeric(18,2) NOT NULL,
  currency_code varchar(3) NOT NULL,
  issued_on date,
  cleared_on date,
  voided_on date,
  reference_number varchar(50),
  billing_account_id uuid,
  replaces_disbursement_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_disbursement PRIMARY KEY (disbursement_id)
);
COMMENT ON TABLE disbursement IS 'Money paid out by the insurer for any purpose: claim payment, premium refund, commission, annuity payout, provider remittance.';

CREATE TABLE invoice (
  invoice_id uuid NOT NULL,
  billing_account_id uuid NOT NULL,
  invoice_number varchar(30) NOT NULL,
  invoice_status text NOT NULL CONSTRAINT ck_invoice_invoice_status CHECK (invoice_status IN ('PLANNED', 'BILLED', 'PARTIALLY_PAID', 'PAID', 'PAST_DUE', 'CANCELLED', 'WRITTEN_OFF')),
  invoice_date date NOT NULL,
  due_date date NOT NULL,
  period_start_date date,
  period_end_date date,
  total_amount numeric(18,2) NOT NULL,
  document_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_invoice PRIMARY KEY (invoice_id),
  CONSTRAINT uq_invoice_invoice_number UNIQUE (invoice_number)
);
COMMENT ON TABLE invoice IS 'A bill or installment notice issued on a billing account.';

CREATE TABLE invoice_line (
  invoice_line_id uuid NOT NULL,
  invoice_id uuid NOT NULL,
  policy_id uuid,
  premium_transaction_id uuid,
  enrollment_id uuid,
  premium_charge_type text NOT NULL CONSTRAINT ck_invoice_line_premium_charge_type CHECK (premium_charge_type IN ('PREMIUM', 'MINIMUM_PREMIUM_ADJUSTMENT', 'POLICY_FEE', 'INSTALLMENT_FEE', 'INSPECTION_FEE', 'BROKER_FEE', 'PREMIUM_TAX', 'SURPLUS_LINES_TAX', 'STAMPING_FEE', 'STATE_SURCHARGE', 'TERRORISM_PREMIUM', 'EXPENSE_CONSTANT', 'OTHER_FEE')),
  installment_number integer,
  description varchar(200),
  amount numeric(18,2) NOT NULL,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_invoice_line PRIMARY KEY (invoice_line_id)
);
COMMENT ON TABLE invoice_line IS 'A charge on an invoice: an installment of premium, a fee or a tax for one policy, traceable to the premium transaction it bills.';

CREATE TABLE payment (
  payment_id uuid NOT NULL,
  billing_account_id uuid,
  payer_party_id uuid,
  payment_method text NOT NULL CONSTRAINT ck_payment_payment_method CHECK (payment_method IN ('ACH', 'CREDIT_CARD', 'DEBIT_CARD', 'CHECK', 'WIRE', 'CASH', 'LOCKBOX', 'DIGITAL_WALLET', 'VIRTUAL_CARD', 'PUSH_TO_DEBIT', 'INTERNAL_TRANSFER')),
  payment_status text NOT NULL CONSTRAINT ck_payment_payment_status CHECK (payment_status IN ('PENDING', 'SETTLED', 'RETURNED', 'REVERSED', 'REFUNDED', 'SUSPENSE')),
  payment_instrument_id uuid,
  amount numeric(18,2) NOT NULL,
  received_at timestamptz NOT NULL,
  deposit_date date,
  accounting_date date,
  reference_number varchar(50),
  batch_number varchar(50),
  reverses_payment_id uuid,
  return_reason_code varchar(20),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_payment PRIMARY KEY (payment_id)
);
COMMENT ON TABLE payment IS 'Money received from or on behalf of a payor.';

CREATE TABLE payment_application (
  payment_application_id uuid NOT NULL,
  payment_id uuid NOT NULL,
  invoice_line_id uuid,
  policy_id uuid,
  amount numeric(18,2) NOT NULL,
  applied_at timestamptz NOT NULL,
  reverses_payment_application_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_payment_application PRIMARY KEY (payment_application_id)
);
COMMENT ON TABLE payment_application IS 'Application of part of a payment to an invoice line or directly to a policy.';

CREATE TABLE payment_instrument (
  payment_instrument_id uuid NOT NULL,
  party_id uuid NOT NULL,
  payment_method text NOT NULL CONSTRAINT ck_payment_instrument_payment_method CHECK (payment_method IN ('ACH', 'CREDIT_CARD', 'DEBIT_CARD', 'CHECK', 'WIRE', 'CASH', 'LOCKBOX', 'DIGITAL_WALLET', 'VIRTUAL_CARD', 'PUSH_TO_DEBIT', 'INTERNAL_TRANSFER')),
  payment_instrument_status text NOT NULL CONSTRAINT ck_payment_instrument_payment_instrument_status CHECK (payment_instrument_status IN ('ACTIVE', 'EXPIRED', 'REVOKED', 'FAILED_VERIFICATION')),
  token varchar(200) NOT NULL,
  last_four varchar(4),
  institution_name varchar(100),
  card_brand varchar(20),
  expiry_month integer,
  expiry_year integer,
  authorization_document_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_payment_instrument PRIMARY KEY (payment_instrument_id)
);
COMMENT ON TABLE payment_instrument IS 'A tokenized bank account or card a party has authorized for payments or payouts. Raw account and card numbers are never stored.';

CREATE TABLE payment_plan (
  payment_plan_id uuid NOT NULL,
  plan_code varchar(30) NOT NULL,
  name varchar(255) NOT NULL,
  billing_frequency text NOT NULL CONSTRAINT ck_payment_plan_billing_frequency CHECK (billing_frequency IN ('FULL_PAY', 'SEMI_ANNUAL', 'QUARTERLY', 'MONTHLY', 'BIWEEKLY', 'WEEKLY', 'PER_PAYROLL')),
  installment_count integer,
  down_payment_percent numeric(9,4),
  installment_fee_amount numeric(18,2),
  days_billed_before_due integer,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_payment_plan PRIMARY KEY (payment_plan_id),
  CONSTRAINT uq_payment_plan_plan_code UNIQUE (plan_code)
);
COMMENT ON TABLE payment_plan IS 'An installment schedule offered to payors.';

CREATE TABLE reinsurance_contract (
  reinsurance_contract_id uuid NOT NULL,
  contract_number varchar(50) NOT NULL,
  name varchar(255) NOT NULL,
  reinsurance_contract_type text NOT NULL CONSTRAINT ck_reinsurance_contract_reinsurance_contract_type CHECK (reinsurance_contract_type IN ('TREATY', 'FACULTATIVE')),
  reinsurance_direction text NOT NULL CONSTRAINT ck_reinsurance_contract_reinsurance_direction CHECK (reinsurance_direction IN ('CEDED', 'ASSUMED')),
  reinsurance_form text NOT NULL CONSTRAINT ck_reinsurance_contract_reinsurance_form CHECK (reinsurance_form IN ('QUOTA_SHARE', 'SURPLUS_SHARE', 'PER_RISK_EXCESS', 'PER_OCCURRENCE_EXCESS', 'CATASTROPHE_EXCESS', 'AGGREGATE_STOP_LOSS', 'CLASH', 'YEARLY_RENEWABLE_TERM', 'COINSURANCE', 'MODIFIED_COINSURANCE', 'FUNDS_WITHHELD', 'LOSS_PORTFOLIO_TRANSFER', 'ADVERSE_DEVELOPMENT_COVER')),
  reinsurance_basis text NOT NULL CONSTRAINT ck_reinsurance_contract_reinsurance_basis CHECK (reinsurance_basis IN ('LOSSES_OCCURRING', 'RISKS_ATTACHING', 'CLAIMS_MADE', 'IN_FORCE_NEW_AND_RENEWAL')),
  reinsurance_contract_status text NOT NULL CONSTRAINT ck_reinsurance_contract_reinsurance_contract_status CHECK (reinsurance_contract_status IN ('QUOTED', 'BOUND', 'IN_FORCE', 'EXPIRED', 'CANCELLED', 'RUN_OFF', 'COMMUTED')),
  cedent_insurer_id uuid NOT NULL,
  broker_party_id uuid,
  currency_code varchar(3) NOT NULL,
  effective_date date NOT NULL,
  expiration_date date,
  renewal_of_contract_id uuid,
  is_inuring_to_other_contracts boolean,
  includes_alae varchar(30),
  contract_document_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_contract PRIMARY KEY (reinsurance_contract_id),
  CONSTRAINT uq_reinsurance_contract_contract_number UNIQUE (contract_number)
);
COMMENT ON TABLE reinsurance_contract IS 'A reinsurance treaty or facultative certificate for one contract period.';

CREATE TABLE reinsurance_layer (
  reinsurance_layer_id uuid NOT NULL,
  reinsurance_contract_id uuid NOT NULL,
  layer_number integer NOT NULL,
  attachment_point_amount numeric(18,2),
  limit_amount numeric(18,2),
  aggregate_limit_amount numeric(18,2),
  aggregate_deductible_amount numeric(18,2),
  ceded_share_percent numeric(9,4),
  maximum_line_count numeric(18,6),
  ceding_commission_percent numeric(9,4),
  has_sliding_scale_commission boolean,
  profit_commission_percent numeric(9,4),
  reinstatement_count integer,
  reinstatement_premium_percent numeric(9,4),
  rate_on_subject_premium_percent numeric(9,4),
  deposit_premium_amount numeric(18,2),
  minimum_premium_amount numeric(18,2),
  estimated_subject_premium_amount numeric(18,2),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_layer PRIMARY KEY (reinsurance_layer_id),
  CONSTRAINT uq_reinsurance_layer_reinsurance_contract_id_layer_number UNIQUE (reinsurance_contract_id, layer_number)
);
COMMENT ON TABLE reinsurance_layer IS 'A layer or section of a reinsurance contract with its own retention, limit and pricing. Proportional contracts have a single layer carrying the ceded share.';

CREATE TABLE reinsurance_loss_cession (
  reinsurance_loss_cession_id uuid NOT NULL,
  reinsurance_layer_id uuid NOT NULL,
  claim_id uuid,
  claim_financial_transaction_id uuid,
  catastrophe_event_id uuid,
  loss_cession_type text NOT NULL CONSTRAINT ck_reinsurance_loss_cession_loss_cession_type CHECK (loss_cession_type IN ('PAID', 'CASE_RESERVE', 'RECOVERY')),
  claim_cost_category text NOT NULL CONSTRAINT ck_reinsurance_loss_cession_claim_cost_category CHECK (claim_cost_category IN ('INDEMNITY', 'MEDICAL', 'DEFENSE_COST_CONTAINMENT', 'ADJUSTING_OTHER')),
  ceded_amount numeric(18,2) NOT NULL,
  accounting_date date NOT NULL,
  reinsurance_statement_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_loss_cession PRIMARY KEY (reinsurance_loss_cession_id)
);
COMMENT ON TABLE reinsurance_loss_cession IS 'Loss and expense ceded to (or assumed under) a layer, traceable to the claim ledger where computed per claim.';

CREATE TABLE reinsurance_participant (
  reinsurance_participant_id uuid NOT NULL,
  reinsurance_layer_id uuid NOT NULL,
  reinsurer_party_id uuid NOT NULL,
  signed_share_percent numeric(9,4) NOT NULL,
  is_authorized boolean,
  collateral_type varchar(30),
  collateral_amount numeric(18,2),
  financial_strength_rating varchar(10),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_participant PRIMARY KEY (reinsurance_participant_id),
  CONSTRAINT uq_reinsurance_participant_reinsurance_layer_id_reinsu_c53998c3 UNIQUE (reinsurance_layer_id, reinsurer_party_id)
);
COMMENT ON TABLE reinsurance_participant IS 'A reinsurer''s participation in a layer.';

CREATE TABLE reinsurance_policy_cession (
  reinsurance_policy_cession_id uuid NOT NULL,
  reinsurance_layer_id uuid NOT NULL,
  policy_id uuid NOT NULL,
  policy_coverage_id uuid,
  policy_risk_id uuid,
  ceded_percent numeric(9,4),
  retained_amount numeric(18,2),
  ceded_amount numeric(18,2),
  certificate_number varchar(50),
  effective_date date NOT NULL,
  end_date date,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_policy_cession PRIMARY KEY (reinsurance_policy_cession_id)
);
COMMENT ON TABLE reinsurance_policy_cession IS 'Attachment of a policy or coverage to a reinsurance layer: every facultative placement, and treaty cessions where the share varies by risk (surplus share, life automatic cessions).';

CREATE TABLE reinsurance_premium_cession (
  reinsurance_premium_cession_id uuid NOT NULL,
  reinsurance_layer_id uuid NOT NULL,
  premium_transaction_id uuid,
  policy_id uuid,
  premium_type varchar(30) NOT NULL,
  ceded_premium_amount numeric(18,2) NOT NULL,
  ceding_commission_amount numeric(18,2),
  earning_start_date date,
  earning_end_date date,
  accounting_date date NOT NULL,
  reinsurance_statement_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_premium_cession PRIMARY KEY (reinsurance_premium_cession_id)
);
COMMENT ON TABLE reinsurance_premium_cession IS 'Premium and commission ceded to (or assumed under) a layer, at policy or bulk level.';

CREATE TABLE reinsurance_scope (
  reinsurance_scope_id uuid NOT NULL,
  reinsurance_contract_id uuid NOT NULL,
  scope_inclusion text NOT NULL CONSTRAINT ck_reinsurance_scope_scope_inclusion CHECK (scope_inclusion IN ('INCLUDE', 'EXCLUDE')),
  line_of_business_code varchar(30),
  asl_code varchar(10),
  jurisdiction_code varchar(6),
  product_id uuid,
  cause_of_loss_code varchar(30),
  description varchar(500),
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_scope PRIMARY KEY (reinsurance_scope_id)
);
COMMENT ON TABLE reinsurance_scope IS 'Business included in or excluded from a reinsurance contract by line, statutory line, state or product.';

CREATE TABLE reinsurance_statement (
  reinsurance_statement_id uuid NOT NULL,
  reinsurance_contract_id uuid NOT NULL,
  reinsurance_participant_id uuid,
  reinsurance_statement_status text NOT NULL CONSTRAINT ck_reinsurance_statement_reinsurance_statement_status CHECK (reinsurance_statement_status IN ('DRAFT', 'ISSUED', 'AGREED', 'DISPUTED', 'SETTLED')),
  period_start_date date NOT NULL,
  period_end_date date NOT NULL,
  premium_amount numeric(18,2),
  commission_amount numeric(18,2),
  paid_loss_amount numeric(18,2),
  balance_due_amount numeric(18,2) NOT NULL,
  due_date date,
  settled_on date,
  payment_id uuid,
  disbursement_id uuid,
  created_at timestamptz NOT NULL,
  created_by varchar(100),
  updated_at timestamptz,
  updated_by varchar(100),
  row_version integer NOT NULL,
  CONSTRAINT pk_reinsurance_statement PRIMARY KEY (reinsurance_statement_id)
);
COMMENT ON TABLE reinsurance_statement IS 'Periodic account between cedent and a reinsurer for a contract, netting premium, commission and losses to a balance due.';

